/bin/bash -lc "node <<'NODE'
const fs = require('node:fs');
const assert = require('node:assert/strict');
const { JSDOM, VirtualConsole } = require('/opt/stacks/aether/frontend/node_modules/jsdom');
const html = fs.readFileSync('index.html', 'utf8');
const errors = [];
const virtualConsole = new VirtualConsole();
virtualConsole.on('jsdomError', error => errors.push(error.message));
const makePage = saved => new JSDOM(html, {
  url: 'https://wedding.example/', runScripts: 'dangerously', virtualConsole,
  beforeParse(window) { if (saved) window.localStorage.setItem('sam-priya-wedding-rsvp-2027', saved); }
});
const page = makePage();
const w = page.window, d = w.document;
const submit = () => d.getElementById('rsvp-form').dispatchEvent(new w.Event('submit', { bubbles: true, cancelable: true }));
const change = el => el.dispatchEvent(new w.Event('change', { bubbles: true }));
submit();
assert.match(d.getElementById('name-error').textContent, /enter your name/);
assert.match(d.getElementById('attendance-error').textContent, /whether you can attend/);
assert.equal(d.activeElement.id, 'guest-name');
d.getElementById('guest-name').value = '  Taylor Morgan  ';
const yes = d.querySelector('[value=\"yes\"]'); yes.checked = true; change(yes);
d.getElementById('increase').click();
assert.equal(d.getElementById('guest-count').value, '2');
d.getElementById('dietary').value = 'One vegetarian; nut allergy';
submit();
assert.equal(d.getElementById('confirmation').hidden, false);
assert.match(d.getElementById('response-summary').textContent, /Taylor Morgan · Attending · 2 guests/);
let saved = w.localStorage.getItem('sam-priya-wedding-rsvp-2027');
assert.equal(JSON.parse(saved).dietary, 'One vegetarian; nut allergy');
const restored = makePage(saved);
assert.equal(restored.window.document.getElementById('confirmation').hidden, false);
assert.equal(restored.window.document.getElementById('guest-count').value, '2');
d.getElementById('edit-response').click();
assert.equal(d.getElementById('rsvp-form').hidden, false);
d.getElementById('guest-count').value = '1.5';
submit();
assert.match(d.getElementById('count-error').textContent, /whole number/);
const no = d.querySelector('[value=\"no\"]'); no.checked = true; change(no);
assert.equal(d.getElementById('attending-fields').hidden, true);
submit();
saved = JSON.parse(w.localStorage.getItem('sam-priya-wedding-rsvp-2027'));
assert.equal(saved.guests, 0);
assert.equal(saved.dietary, '');
assert.match(d.getElementById('response-summary').textContent, /Unable to attend/);
const blocked = makePage();
blocked.window.eval(\"Storage.prototype.setItem = function () { throw new Error('Blocked'); }\");
const bd = blocked.window.document;
bd.getElementById('guest-name').value = 'Alex';
bd.querySelector('[value=\"no\"]').checked = true;
bd.getElementById('rsvp-form').dispatchEvent(new blocked.window.Event('submit', { cancelable: true }));
assert.match(bd.getElementById('save-error').textContent, /could not save/);
assert.equal(bd.getElementById('rsvp-form').hidden, false);
const corrupt = makePage('{broken');
assert.equal(corrupt.window.document.getElementById('rsvp-form').hidden, false);
assert.equal(errors.length, 0, errors.join('\\n'));
for (const label of d.querySelectorAll('label[for]')) assert.ok(d.getElementById(label.htmlFor));
console.log('PASS: validation, acceptance, guest stepper, dietary storage, persistence, editing, decline, invalid counts, blocked storage, corrupt storage, labels, and script execution.');
for (const dom of [page, restored, blocked, corrupt]) dom.window.close();
NODE"

